actions.script:
// Acquire the Barcode/POS organization -> product lock order before updating pseudoId.
if (curProd.ownerPartyId) ec.entity.find('mantle.party.Party').condition('partyId',curProd.ownerPartyId).forUpdate(true).disableAuthz().one()
ec.entity.find('mantle.product.Product').condition('productId',productId).forUpdate(true).one()

// Only editor fields may be changed; never accept owner, IDs, stock or document state.
productChanges = [productId:productId, ownerPartyId:curProd.ownerPartyId]
def supplied = ec.web.parameters
def limits = [productName:255, printName:255, pseudoId:100, description:500, comments:2000, hsnCode:20, sacCode:20]
limits.each { key, max ->
    if (supplied.containsKey(key)) {
        def value = (supplied[key] ?: '').toString().trim()
        if (value.length() > max || value.any { Character.isISOControl((char)it) && !(key in ['description','comments'] && it in ['\n','\r','\t']) })
            ec.message.addError(key+' is too long or contains unsupported characters.')
        productChanges[key] = value ?: null
    }
}
if (supplied.containsKey('productName') && !productChanges.productName) ec.message.addError('Product Name is required.')
def nextName=productChanges.containsKey('productName') ? productChanges.productName : curProd.productName
// A null override follows future renames. A deliberately different name stays fixed.
if (productChanges.containsKey('printName') && productChanges.printName==nextName) productChanges.printName=null
[productTypeEnumId:['PtAsset','PtService','PtDigitalAsset'], uqcEnumId:['','NOS','KGS','MTR','PCS','LTR'],
    isGstExempt:['Y','N'],enableBatchTracking:['Y','N'],enableSerialTracking:['Y','N']].each { key, values ->
    if (supplied.containsKey(key)) {
        def value=(supplied[key] ?: '').toString()
        if (!(value in values) && value!=curProd.get(key)) ec.message.addError('Choose a valid '+key+'.')
        else productChanges[key]=value ?: null
    }
}
['mrpAmount','reorderPoint'].each { key ->
    if (supplied.containsKey(key)) {
        def value=(supplied[key] ?: '').toString().trim()
        try {
            def number=value ? new BigDecimal(value) : null
            if (number!=null && (number.signum()<0 || number.precision()>18 || number.scale()>6)) throw new IllegalArgumentException()
            productChanges[key]=number
        } catch (Exception ignored) { ec.message.addError(key+' must be 0 or a positive number (up to 6 decimal places).') }
    }
}
if (supplied.containsKey('gstSlabId')) {
    def slab=(supplied.gstSlabId ?: '').toString()
    if (slab && !ec.entity.find('zenith.erp.india.IndiaGstSlab').condition('gstSlabId',slab).one()) ec.message.addError('Choose an existing GST rate.')
    else productChanges.gstSlabId=slab ?: null
}
preparedImage=null
def image=(supplied.imageData ?: '').toString()
if (image) {
    try {
        if (image.length()>2800000 || !(image ==~ /data:image\/(png|jpeg);base64,[A-Za-z0-9+\/=]+/)) throw new IllegalArgumentException()
        byte[] bytes=Base64.decoder.decode(image.substring(image.indexOf(',')+1))
        if (bytes.length>2097152) throw new IllegalArgumentException()
        def stream=javax.imageio.ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))
        try {
            def readers=javax.imageio.ImageIO.getImageReaders(stream)
            if (!readers.hasNext()) throw new IllegalArgumentException()
            def reader=readers.next()
            try {
                reader.setInput(stream)
                if (reader.getWidth(0)>4096 || reader.getHeight(0)>4096) throw new IllegalArgumentException()
                def detected=reader.getFormatName().toLowerCase()
                if (!(detected in ['jpeg','jpg','png'])) throw new IllegalArgumentException()
                def format=detected in ['jpeg','jpg'] ? 'jpeg' : 'png'
                def buffer=new ByteArrayOutputStream()
                javax.imageio.ImageIO.write(reader.read(0),format,buffer)
                if (buffer.size()>2097152) throw new IllegalArgumentException()
                preparedImage='data:image/'+format+';base64,'+Base64.encoder.encodeToString(buffer.toByteArray())
            } finally { reader.dispose() }
        } finally { stream.close() }
    } catch (Exception ignored) { ec.message.addError('Use a valid JPG or PNG image, at most 2 MB and 4096 pixels per side.') }
}

if.script:
if (pseudoId ==~ /\d{8}|\d{12}|\d{13}/) {
    def x = pseudoId; int n = x.length(); int sum = 0
    for (int i = 0; i < n-1; i++) { int d = Character.getNumericValue(x.charAt(n-2-i)); sum += (i % 2 == 0) ? d*3 : d }
    if (((10 - (sum % 10)) % 10) != Character.getNumericValue(x.charAt(n-1)))
        ec.message.addMessage("Heads up: '" + pseudoId + "' looks like an EAN/UPC barcode but its check digit is invalid — please re-scan or double-check. (Saved anyway.)")
}

actions.script:
try {
    def _newMrp = (mrpAmount != null && mrpAmount.toString().trim() != '') ? (mrpAmount.toString().trim() as BigDecimal) : null
    def _oldMrp = curProd?.mrpAmount != null ? (curProd.mrpAmount as BigDecimal) : null
    if (_newMrp != null && (_oldMrp == null || _oldMrp.compareTo(_newMrp) != 0)) {
        def _prev = _oldMrp ?: 0G
        def _reasonIn = ec.context.changeReason
        def _reason = (_reasonIn != null && _reasonIn.toString().trim()) ? _reasonIn.toString().trim()
                      : ((_prev.compareTo(0G) == 0) ? 'Initial price set' : 'Price updated')
        ec.service.sync().name("create#zenith.erp.pricing.PriceChangeLog").parameters([
            organizationPartyId: curProd.ownerPartyId, productId: productId,
            previousPrice: _prev, newPrice: _newMrp, changeReason: _reason,
            changedByUserId: ec.user.userId, changeDate: ec.user.nowTimestamp]).call()
    }
} catch (Throwable e) { ec.logger.warn("Price history log skipped for product " + productId + ": " + e.message) }

def imageRow=ec.entity.find('zenith.erp.inventory.ProductEditorImage').condition('productId',productId)
    .condition('organizationPartyId',curProd.ownerPartyId).one()
if (preparedImage) {
    if (imageRow) { imageRow.imageData=preparedImage;imageRow.update() }
    else ec.entity.makeValue('zenith.erp.inventory.ProductEditorImage').setAll([productId:productId,organizationPartyId:curProd.ownerPartyId,imageData:preparedImage]).create()
} else if (ec.web.parameters.removeImage=='Y' && imageRow) imageRow.delete()

if.script:
// ZE-INV-IV-035 f/u: fully-qualified below (no `import` — this script is now nested in <if allowed>,
// and a Groovy import must be top-level, not inside a block).
def ef = ec.entity
def ownedFacilities=ef.find('mantle.facility.Facility').condition('ownerPartyId',product.ownerPartyId).list()*.facilityId as Set
stockList=stockList.findAll { ownedFacilities.contains(it.facilityId) }
if (productImage?.organizationPartyId != product.ownerPartyId) productImage=null
for (def stock : stockList) {
    totalQoh += (stock.totalQoh ?: 0)
}
// ZE-INV-001 f/u: per-store Stock Value from Assets directly (valuationRate -> acquireCost ->
// product MRP), NOT the view's totalValue (= sum(acquireCost): 0 for MRP-priced stock). Keyed
// facility|lot to line up with this product's by-facility rows. Same fix as StockLevels.
stockValueByRow = [:]
def _mrp = (product?.mrpAmount ?: 0G) as java.math.BigDecimal
def _pa = ef.find("mantle.product.asset.Asset")
            .condition("productId", productId)
            .condition("ownerPartyId", product.ownerPartyId)
            .condition("assetTypeEnumId", "AstTpInventory")
            .condition("quantityOnHandTotal", org.moqui.entity.EntityCondition.GREATER_THAN, 0G).list()
for (a in _pa) {
    def qoh = (a.quantityOnHandTotal ?: 0G) as java.math.BigDecimal
    def vr = a.valuationRate ? (a.valuationRate as java.math.BigDecimal) : null
    def ac = a.acquireCost ? (a.acquireCost as java.math.BigDecimal) : null
    def rate = (vr != null && vr > 0G) ? vr : ((ac != null && ac > 0G) ? ac : _mrp)
    def val = qoh * (rate ?: 0G)
    def k = (a.facilityId ?: '') + '|' + (a.lotId ?: '')
    stockValueByRow[k] = (stockValueByRow[k] ?: 0G) + val
}
totalAtp=stockList.sum { it.totalAtp ?: 0G } ?: 0G
totalStockValue=stockList.sum { stockValueByRow[(it.facilityId ?: '')+'|'+(it.lotId ?: '')] ?: 0G } ?: 0G
